+---
+// Starlight's own Header.astro has no <slot/>, so wrapping it silently drops
+// any extra content passed as children — this reconstructs it instead,
+// importing the same sub-components, to add a per-page PDF download link.
+// See CLAUDE.md for why: the link must be per-document (index.pdf, tool.pdf,
+// future kdoc-derived pages), not one shared sidebar entry for a merged PDF.
+import config from 'virtual:starlight/user-config';
+
+import LanguageSelect from 'virtual:starlight/components/LanguageSelect';
+import Search from 'virtual:starlight/components/Search';
+import SiteTitle from 'virtual:starlight/components/SiteTitle';
+import SocialIcons from 'virtual:starlight/components/SocialIcons';
+import ThemeSelect from 'virtual:starlight/components/ThemeSelect';
+
+const shouldRenderSearch =
+	config.pagefind || config.components.Search !== '@astrojs/starlight/components/Search.astro';
+
+// Mirrors site/myst/myst.yml's `toc` and astro.config.mjs's sidebar `items`
+// (same three-way sync this repo already documents in CLAUDE.md) — the pages
+// that actually have a PDF export. An allowlist, not "does a route id exist,"
+// because 404.astro also has a (non-empty, non-''), id of "404" — id presence
+// alone can't distinguish real content pages from Astro's own special routes.
+const PAGES_WITH_PDF = new Set(['', 'tool']);
+
+// `Astro.locals.starlightRoute` is a newer Starlight API (doesn't exist in
+// the ^0.30.0 pinned here — grepped node_modules to confirm before assuming
+// it). In 0.30.x, Starlight passes route data as Astro.props instead: Header
+// receives it as {...Astro.props} per the installed component's own source.
+const routeId = (Astro.props as { id?: string }).id;
+// Starlight's route id is '' for the homepage, not 'index' — matches this
+// site's own PDF export filenames (site/myst/index.md -> exports/index.pdf).
+const slug = routeId === '' ? 'index' : routeId;
+const base = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
+const pdfHref = routeId !== undefined && PAGES_WITH_PDF.has(routeId) ? `${base}${slug}.pdf` : undefined;
+---
+
+<div class="header">
+	<div class="title-wrapper sl-flex">
+		<SiteTitle />
+	</div>
+	<div class="sl-flex print:hidden">
+		{shouldRenderSearch && <Search />}
+	</div>
+	<div class="sl-hidden md:sl-flex print:hidden right-group">
+		{pdfHref && <a href={pdfHref} class="pdf-download-link" rel="nofollow">Download as PDF</a>}
+		<div class="sl-flex social-icons">
+			<SocialIcons />
+		</div>
+		<ThemeSelect />
+		<LanguageSelect />
+	</div>
+</div>
+
+<style>
+	@layer starlight.core {
+		.header {
+			display: flex;
+			gap: var(--sl-nav-gap);
+			justify-content: space-between;
+			align-items: center;
+			height: 100%;
+		}
+
+		.title-wrapper {
+			overflow: clip;
+			padding: 0.25rem;
+			margin: -0.25rem;
+			min-width: 0;
+		}
+
+		.right-group,
+		.social-icons {
+			gap: 1rem;
+			align-items: center;
+		}
+		.social-icons::after {
+			content: '';
+			height: 2rem;
+			border-inline-end: 1px solid var(--sl-color-gray-5);
+		}
+
+		.pdf-download-link {
+			font-size: var(--sl-text-sm);
+			color: var(--sl-color-gray-2);
+			text-decoration: none;
+			white-space: nowrap;
+		}
+		.pdf-download-link:hover {
+			color: var(--sl-color-white);
+			text-decoration: underline;
+		}
+
+		@media (min-width: 50rem) {
+			:global(:root[data-has-sidebar]) {
+				--__sidebar-pad: calc(2 * var(--sl-nav-pad-x));
+			}
+			:global(:root:not([data-has-toc])) {
+				--__toc-width: 0rem;
+			}
+			.header {
+				--__sidebar-width: max(0rem, var(--sl-content-inline-start, 0rem) - var(--sl-nav-pad-x));
+				--__main-column-fr: calc(
+						(
+								100% + var(--__sidebar-pad, 0rem) - var(--__toc-width, var(--sl-sidebar-width)) -
+									(2 * var(--__toc-width, var(--sl-nav-pad-x))) - var(--sl-content-inline-start, 0rem) -
+									var(--sl-content-width)
+							) / 2
+					);
+				display: grid;
+				grid-template-columns:
+					minmax(
+						calc(var(--__sidebar-width) + max(0rem, var(--__main-column-fr) - var(--sl-nav-gap))),
+						auto
+					)
+					1fr
+					auto;
+				align-content: center;
+			}
+		}
+	}
+</style>
